ansible/roles/core/tasks/main.json:
[
  {
    "ansible.builtin.package": {
      "name": [
        "docker.io",
        "docker-compose"
      ],
      "state": "present",
      "update_cache": true
    },
    "name": "Install the container engine"
  },
  {
    "ansible.builtin.systemd": {
      "enabled": true,
      "name": "docker",
      "state": "started"
    },
    "name": "Start the container engine"
  },
  {
    "ansible.builtin.file": {
      "mode": "0700",
      "path": "/opt/bromigos-lab",
      "state": "directory"
    },
    "name": "Make the lab folder"
  },
  {
    "ansible.builtin.copy": {
      "dest": "/opt/bromigos-lab/",
      "directory_mode": "0755",
      "mode": "0644",
      "src": "{{ playbook_dir }}/../../compose/"
    },
    "name": "Copy the reviewed container definitions"
  },
  {
    "ansible.builtin.shell": {
      "chdir": "/opt/bromigos-lab",
      "cmd": "if docker compose version >/dev/null 2>&1; then docker compose up -d; else docker-compose up -d; fi"
    },
    "changed_when": false,
    "name": "Start selected services without deleting data"
  }
]

ansible/roles/monitoring/tasks/main.json:
[
  {
    "ansible.builtin.package": {
      "name": [
        "docker.io",
        "docker-compose"
      ],
      "state": "present",
      "update_cache": true
    },
    "name": "Install monitoring engine"
  },
  {
    "ansible.builtin.systemd": {
      "enabled": true,
      "name": "docker",
      "state": "started"
    },
    "name": "Keep container engine running"
  },
  {
    "ansible.builtin.copy": {
      "dest": "/opt/bromigos-monitoring/",
      "directory_mode": "0755",
      "mode": "0644",
      "src": "{{ playbook_dir }}/../../monitoring/"
    },
    "name": "Copy reviewed monitoring settings",
    "register": "monitoring_files"
  },
  {
    "ansible.builtin.file": {
      "mode": "0755",
      "path": "/opt/bromigos-monitoring/textfile",
      "state": "directory"
    },
    "name": "Create exporter textfile folder"
  },
  {
    "ansible.builtin.shell": {
      "chdir": "/opt/bromigos-monitoring",
      "cmd": "if docker compose version >/dev/null 2>&1; then docker compose -p bromigos-monitoring up -d {{ \"--force-recreate\" if monitoring_files.changed else \"\" }}; else docker-compose -p bromigos-monitoring up -d {{ \"--force-recreate\" if monitoring_files.changed else \"\" }}; fi"
    },
    "changed_when": false,
    "name": "Start monitoring without removing state"
  },
  {
    "ansible.builtin.copy": {
      "content": "#!/bin/sh\nset -eu\nstamp=$(docker exec $(docker ps -q --filter label=com.docker.compose.service=restic --filter label=com.docker.compose.project=bromigos-lab) stat -c %Y /status/last-success)\nprintf \"lab_backup_last_success_timestamp_seconds %s\\n\" \"$stamp\" > /opt/bromigos-monitoring/textfile/backup.prom.tmp\nmv /opt/bromigos-monitoring/textfile/backup.prom.tmp /opt/bromigos-monitoring/textfile/backup.prom\n",
      "dest": "/opt/bromigos-monitoring/backup-metric",
      "mode": "0700"
    },
    "name": "Write backup metric collector"
  },
  {
    "ansible.builtin.copy": {
      "content": "[Service]\nType=oneshot\nExecStart=/opt/bromigos-monitoring/backup-metric\n",
      "dest": "/etc/systemd/system/bromigos-backup-metric.service"
    },
    "name": "Write backup metric service"
  },
  {
    "ansible.builtin.copy": {
      "content": "[Timer]\nOnBootSec=1min\nOnUnitActiveSec=1min\n[Install]\nWantedBy=timers.target\n",
      "dest": "/etc/systemd/system/bromigos-backup-metric.timer"
    },
    "name": "Write backup metric timer"
  },
  {
    "ansible.builtin.systemd": {
      "daemon_reload": true,
      "enabled": true,
      "name": "bromigos-backup-metric.timer",
      "state": "started"
    },
    "name": "Start backup metric timer"
  }
]

