compose/compose.yaml:
{
  "services": {
    "caddy": {
      "image": "caddy:2.11.7",
      "ports": [
        "127.0.0.1:80:80",
        "127.0.0.1:443:443"
      ],
      "restart": "unless-stopped",
      "volumes": [
        "./Caddyfile:/etc/caddy/Caddyfile:ro",
        "caddy-data:/data"
      ]
    },
    "homepage": {
      "environment": {
        "HOMEPAGE_ALLOWED_HOSTS": "*"
      },
      "image": "ghcr.io/gethomepage/homepage:v2.5.0",
      "restart": "unless-stopped",
      "volumes": [
        "./homepage:/app/config"
      ]
    },
    "netdata": {
      "environment": {
        "DO_NOT_TRACK": "1"
      },
      "image": "netdata/netdata:v2.12.1",
      "restart": "unless-stopped",
      "volumes": [
        "netdata-data:/var/lib/netdata",
        "/proc:/host/proc:ro",
        "/sys:/host/sys:ro"
      ]
    },
    "restic": {
      "command": [
        "while true; do restic snapshots >/dev/null 2>&1 || restic init; restic backup /data && touch /status/last-success; sleep 86400; done"
      ],
      "entrypoint": [
        "/bin/sh",
        "-c"
      ],
      "environment": {
        "RESTIC_PASSWORD_FILE": "/run/secrets/restic",
        "RESTIC_REPOSITORY": "/repository"
      },
      "image": "restic/restic:0.19.1",
      "restart": "unless-stopped",
      "volumes": [
        "/mnt/backups:/repository",
        "/opt/bromigos-lab:/data/config:ro",
        "caddy-data:/data/caddy:ro",
        "netdata-data:/data/netdata:ro",
        "./restic-password:/run/secrets/restic:ro",
        "backup-status:/status"
      ]
    }
  },
  "volumes": {
    "backup-status": {},
    "caddy-data": {},
    "netdata-data": {}
  }
}

