monitoring/config/rules.json:
{
  "groups": [
    {
      "name": "lab",
      "rules": [
        {
          "alert": "NodeDown",
          "annotations": {
            "summary": "A node exporter is unreachable"
          },
          "expr": "up{job=~\".*node.*\"} == 0",
          "for": "2m",
          "labels": {
            "severity": "warning"
          }
        },
        {
          "alert": "DiskFilling",
          "annotations": {
            "summary": "A disk has less than 15 percent free"
          },
          "expr": "node_filesystem_avail_bytes{fstype!~\"tmpfs|overlay\"}/node_filesystem_size_bytes < 0.15",
          "for": "10m",
          "labels": {
            "severity": "warning"
          }
        },
        {
          "alert": "ServiceDown",
          "annotations": {
            "summary": "A provisioned service does not answer"
          },
          "expr": "probe_success == 0",
          "for": "2m",
          "labels": {
            "severity": "warning"
          }
        },
        {
          "alert": "CertificateExpiring",
          "annotations": {
            "summary": "A certificate expires within 14 days"
          },
          "expr": "probe_ssl_earliest_cert_expiry - time() < 14*86400",
          "for": "10m",
          "labels": {
            "severity": "warning"
          }
        },
        {
          "alert": "BackupStale",
          "annotations": {
            "summary": "No successful backup within 30 hours"
          },
          "expr": "time()-lab_backup_last_success_timestamp_seconds > 30*3600 or absent(lab_backup_last_success_timestamp_seconds)",
          "for": "10m",
          "labels": {
            "severity": "warning"
          }
        }
      ]
    }
  ]
}
